package com.fasterxml.jackson.databind.util;

import com.fasterxml.jackson.core.io.NumberInput;
import java.io.*;
import java.math.*;
import java.text.DateFormat;
import java.text.FieldPosition;
import java.text.ParseException;
import java.text.ParsePosition;
import java.text.SimpleDateFormat;
import java.util.*;
import java.util.Date;
import java.util.Locale;
import java.util.TimeZone;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;

/**
 * Unit tests for StdDateFormat._parseDate.
 * Since _parseDate is protected, we use a subclass to access it.
 */
public class StdDateFormat__parseDate_TriageGen1Test {

    private TestableStdDateFormat dateFormat;

    // Subclass to expose the protected method for testing
    private static class TestableStdDateFormat extends StdDateFormat {
        public TestableStdDateFormat() {
            super();
        }

        @Override
        public Date _parseDate(String dateStr, ParsePosition pos) throws java.text.ParseException {
            return super._parseDate(dateStr, pos);
        }
    }

    @Before
    public void setUp() {
        dateFormat = new TestableStdDateFormat();
    }

    @Test
    public void testParseISO8601() throws java.text.ParseException {
        // ISO8601 format
        String isoDate = "2023-10-27T10:00:00Z";
        Date result = dateFormat._parseDate(isoDate, new ParsePosition(0));
        assertNotNull(result);
        // Verify it's not null and parsing succeeded
        assertEquals(isoDate, dateFormat.format(result, new StringBuffer(), new java.text.FormatLocation()));
    }

    @Test
    public void testParseLongTimestamp() throws java.text.ParseException {
        // Stringified simple timestamp (long)
        String longDate = "1698393600000";
        Date result = dateFormat._parseDate(longDate, new ParsePosition(0));
        assertNotNull(result);
        assertEquals(1698393600000L, result.getTime());
    }

    @Test
    public void testParseNegativeLongTimestamp() throws java.text.ParseException {
        // Negative long timestamp
        String negLongDate = "-1698393600000";
        Date result = dateFormat._parseDate(negLongDate, new ParsePosition(0));
        assertNotNull(result);
        assertEquals(-1698393600000L, result.getTime());
    }

    @Test
    public void testParseRFC1123() throws java.text.ParseException {
        // RFC 1123 format
        String rfcDate = "Fri, 27 Oct 2023 10:00:00 GMT";
        Date result = dateFormat._parseDate(rfcDate, new ParsePosition(0));
        assertNotNull(result);
    }

    @Test
    public void testParseFallbackToNull() throws java.text.ParseException {
        // A string that is not ISO8601, not a long, and not RFC1123
        String invalidDate = "not-a-date";
        Date result = dateFormat._parseDate(invalidDate, new ParsePosition(0));
        assertNull(result);
    }

    @Test
    public void testParseMixedContentWithRFC1123() throws java.text.ParseException {
        // Testing the loop logic: if it contains non-digits and isn't ISO or Long
        // "07-Aug-2013" -> i will stop at '-'
        String mixedDate = "07-Aug-2013";
        Date result = dateFormat._parseDate(mixedDate, new ParsePosition(0));
        // This should fall back to parseAsRFC1123 which might return null or a date depending on implementation
        // Given the logic, it goes to RFC1123.
        if (result != null) {
            assertNotNull(result);
        }
    }

    @Test
    public void testParseLongBoundary() throws java.text.ParseException {
        // Testing the logic for NumberInput.inLongRange (simulated by a very long number)
        // If it's too large for a Long, it should fall back to RFC1123
        String hugeNumber = "999999999999999999999999999999";
        Date result = dateFormat._parseDate(hugeNumber, new ParsePosition(0));
        // Should fall back to RFC1123 and likely return null
        assertNull(result);
    }

    @Test
    public void testParseSingleDash() throws java.text.ParseException {
        // Testing the specific condition: if (i > 0 || ch != '-')
        // If the string is just "-", i becomes 0, ch is '-'
        String singleDash = "-";
        Date result = dateFormat._parseDate(singleDash, new ParsePosition(0));
        // Should fall back to RFC1123
        assertNull(result);
    }
}
